body.script:
function hudToken(name, fallback) {
  var v = getComputedStyle(document.documentElement).getPropertyValue(name);
  return (v && v.trim()) ? v.trim() : fallback;
}
async function changeImage(skipOverlay) {
  var currentPlayerId = document.body.getAttribute('data-player-id');
  var countSecs = Math.max(1, parseInt(document.body.getAttribute('data-next-countdown') || '5'));
  var overlay = document.getElementById('ac-next-overlay');
  var countEl = document.getElementById('ac-next-count');
  var mainDiv = document.getElementById('ac-next-main');
  var lastDiv = document.getElementById('ac-next-last');
  var html;
  try {
    var fetchUrl = window.location.href.split('?')[0] + '?exclude=' + currentPlayerId + '&preview=1';
    var r = await fetch(fetchUrl, {cache: 'no-store'});
    if (!r.ok) throw new Error('HTTP ' + r.status);
    html = await r.text();
  } catch(e) {
    console.error('Next player load failed:', e);
    window.location.reload();
    return;
  }
  var parser = new DOMParser();
  var newDoc = parser.parseFromString(html, 'text/html');
  if (!newDoc.body || !newDoc.body.getAttribute('data-player-id')) {
    window.location.replace(window.location.href);
    return;
  }
  var newPlayerId = newDoc.body.getAttribute('data-player-id');
  if (newPlayerId === currentPlayerId) {
    if (mainDiv) mainDiv.style.display = 'none';
    if (lastDiv) lastDiv.style.display = 'block';
    if (overlay) {
      overlay.style.display = 'flex';
      requestAnimationFrame(function() {
        requestAnimationFrame(function() { overlay.style.opacity = '1'; });
      });
    }
    return;
  }
  var zone    = document.querySelector('[data-player-zone]');
  var newZone = newDoc.querySelector('[data-player-zone]');
  if (skipOverlay || !overlay) {
    if (newPlayerId) document.body.setAttribute('data-player-id', newPlayerId);
    var _mf = (newDoc.body && newDoc.body.getAttribute('data-is-mystery')) || '0';
    document.body.setAttribute('data-is-mystery', _mf);
    document.body.removeAttribute('data-mystery-revealed');
    if (zone && newZone) { zone.innerHTML = newZone.innerHTML; }
    if (typeof window.acMysteryApplyFromBody === 'function') { window.acMysteryApplyFromBody(); }
    if (typeof window.acCommitPlayerOnStage === 'function') {
      await window.acCommitPlayerOnStage(newPlayerId);
    }
    return;
  }
  if (mainDiv) mainDiv.style.display = 'flex';
  if (lastDiv) lastDiv.style.display = 'none';
  overlay.style.display = 'flex';
  requestAnimationFrame(function() {
    requestAnimationFrame(function() { overlay.style.opacity = '1'; });
  });
  if (countEl) countEl.textContent = countSecs;
  await new Promise(function(resolve) {
    var remaining = countSecs;
    var tick = setInterval(function() {
      remaining--;
      if (remaining <= 0) { clearInterval(tick); resolve(); }
      else if (countEl) {
        countEl.textContent = remaining;
        countEl.classList.remove('ac-count-pop');
        void countEl.offsetWidth;
        countEl.classList.add('ac-count-pop');
      }
    }, 1000);
  });
  if (newPlayerId) document.body.setAttribute('data-player-id', newPlayerId);
  var _mf2 = (newDoc.body && newDoc.body.getAttribute('data-is-mystery')) || '0';
  document.body.setAttribute('data-is-mystery', _mf2);
  document.body.removeAttribute('data-mystery-revealed');
  if (zone && newZone) { zone.innerHTML = newZone.innerHTML; }
  if (typeof window.acMysteryApplyFromBody === 'function') { window.acMysteryApplyFromBody(); }
  if (typeof window.acCommitPlayerOnStage === 'function') {
    await window.acCommitPlayerOnStage(newPlayerId);
  }
  overlay.style.opacity = '0';
  setTimeout(function() { overlay.style.display = 'none'; }, 400);
}
function closeNextOverlay() {
  var ov = document.getElementById('ac-next-overlay');
  if (!ov) return;
  ov.style.opacity = '0';
  setTimeout(function() { ov.style.display = 'none'; }, 400);
}
document.addEventListener('keydown', function(event) {
  if (event.code === 'Space') {
    event.preventDefault();
    changeImage();
  }
});
function setPlayerUnsold() {
  document.getElementById('unsoldConfirmModal').style.display = 'flex';
}
document.addEventListener('DOMContentLoaded', function() {
  var cancel = document.getElementById('unsoldModalCancel');
  var confirm = document.getElementById('unsoldModalConfirm');
  if (cancel) cancel.addEventListener('click', function() {
    document.getElementById('unsoldConfirmModal').style.display = 'none';
  });
  if (confirm) confirm.addEventListener('click', function() {
    document.getElementById('unsoldConfirmModal').style.display = 'none';
    var playerId = parseInt(document.body.getAttribute('data-player-id'));
    if (!playerId) {
      showUnsoldToast('Error: Player ID not found', true);
      return;
    }
    fetch('/web/dataset/call_kw', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        jsonrpc: '2.0', method: 'call',
        params: {model: 'auction.team.player', method: 'action_unsold', args: [[playerId]], kwargs: {}}
      })
    }).then(function(response) { return response.json(); }).then(function(result) {
      if (result.error) {
        showUnsoldToast('Failed to mark player as unsold', true);
      } else {
        var secs = (result.result && result.result.display_seconds > 0) ? result.result.display_seconds : 5;
        showUnsoldStamp(secs, hudToken('--gold', '#F5C842'), hudToken('--ink-on-accent', '#090912'));
      }
    }).catch(function() {
      showUnsoldToast('Failed to mark player as unsold', true);
    });
  });
});
function showUnsoldToast(message, isError) {
  var toast = document.getElementById('unsoldToast');
  toast.textContent = message;
  toast.style.background = isError ? '#8B0000' : '#1b5e20';
  toast.style.display = 'block';
  setTimeout(function() { toast.style.display = 'none'; }, 3500);
}
function showUnsoldStamp(displaySeconds, stampColor, stampText) {
  if (!document.getElementById('_unsoldStampCSS')) {
    var s = document.createElement('style');
    s.id = '_unsoldStampCSS';
    s.textContent = '@keyframes _unsoldDrop{0%{transform:rotate(-22deg) scale(2.4);opacity:0}100%{transform:rotate(-22deg) scale(1);opacity:.92}}@keyframes _unsoldFadeIn{from{opacity:0}to{opacity:1}}';
    document.head.appendChild(s);
  }
  var img = document.getElementById('loadImage');
  var r = img.getBoundingClientRect();
  var ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;z-index:9500;top:'+r.top+'px;left:'+r.left+'px;width:'+r.width+'px;height:'+r.height+'px;background:rgba(0,0,0,0.48);display:flex;align-items:center;justify-content:center;animation:_unsoldFadeIn .35s ease;pointer-events:none;';
  var stamp = document.createElement('div');
  stamp.style.cssText = 'background:'+stampColor+';color:'+stampText+';font-size:clamp(1.8rem,5vw,3.2rem);font-weight:900;letter-spacing:6px;padding:8px 36px;border:5px solid rgba(255,255,255,0.85);border-radius:6px;box-shadow:0 0 0 3px '+stampColor+',0 8px 40px rgba(0,0,0,.5);opacity:0;animation:_unsoldDrop .5s cubic-bezier(.34,1.3,.64,1) .15s forwards;';
  stamp.textContent = 'UNSOLD';
  var barWrap = document.createElement('div');
  barWrap.style.cssText = 'position:absolute;bottom:12px;left:16px;right:16px;';
  var barTrack = document.createElement('div');
  barTrack.style.cssText = 'background:rgba(255,255,255,0.25);border-radius:4px;height:6px;overflow:hidden;';
  var bar = document.createElement('div');
  bar.style.cssText = 'height:100%;width:100%;background:'+stampColor+';border-radius:4px;transition:width '+displaySeconds+'s linear;';
  barTrack.appendChild(bar);
  barWrap.appendChild(barTrack);
  ov.appendChild(stamp);
  ov.appendChild(barWrap);
  document.body.appendChild(ov);
  requestAnimationFrame(function() { requestAnimationFrame(function() { bar.style.width = '0%'; }); });
  setTimeout(function() { if (ov.parentNode) ov.parentNode.removeChild(ov); changeImage(true); }, displaySeconds * 1000);
}
function resolveAuctionPanelUrl(kind) {
  var el = document.documentElement;
  var url = (kind === 'rp' ? el.dataset.rpUrl : el.dataset.balanceUrl) || '';
  if (url.indexOf('//') === 0) { url = ''; }
  if (url) { return url; }
  var parts = (location.pathname || '').split('/').filter(Boolean);
  var db = parts[0] || '';
  var slug = '';
  if (parts[1] === 'auction' && (parts[2] === 'display_auction' || parts[2] === 'player_selector') && parts[3]) {
    slug = parts[3];
  }
  if (!db || !slug) { return ''; }
  if (kind === 'rp') {
    return '/' + db + '/' + slug + '/auction/display_auction/remaining-players?theme=' + encodeURIComponent(el.dataset.theme || 'vanilla');
  }
  return '/' + db + '/' + slug + '/auction/show/team/balance';
}
function openBidSummary() {
  var frame = document.getElementById('bidSummaryFrame');
  var url = resolveAuctionPanelUrl('balance');
  if (frame && url) {
    var cur = frame.getAttribute('src') || '';
    if (!cur || cur === 'about:blank') { frame.src = url; }
    else {
      try {
        if (frame.contentWindow && typeof frame.contentWindow.refreshBalance === 'function') {
          frame.contentWindow.refreshBalance();
        }
      } catch (e) {}
    }
  }
  document.getElementById('bidSummaryDrawer').style.right = '0';
  document.getElementById('bidSummaryOverlay').style.display = 'block';
  document.body.style.overflow = 'hidden';
}
function closeBidSummary() {
  document.getElementById('bidSummaryDrawer').style.right = '-1150px';
  document.getElementById('bidSummaryOverlay').style.display = 'none';
  document.body.style.overflow = '';
}
function toggleBidSummary() {
  var r = document.getElementById('bidSummaryDrawer').style.right;
  if (r === '0px' || r === '0') { closeBidSummary(); } else { openBidSummary(); }
}
function openRemainingPlayers() {
  document.getElementById('rpFrame').src = resolveAuctionPanelUrl('rp');
  document.getElementById('rpDrawer').style.right = '0';
  document.getElementById('rpOverlay').style.display = 'block';
  document.body.style.overflow = 'hidden';
}
function closeRemainingPlayers() {
  document.getElementById('rpDrawer').style.right = '-900px';
  document.getElementById('rpOverlay').style.display = 'none';
  document.body.style.overflow = '';
}
function toggleRemainingPlayers() {
  var r = document.getElementById('rpDrawer').style.right;
  if (r === '0px' || r === '0') { closeRemainingPlayers(); } else { openRemainingPlayers(); }
}
function toggleFullscreen() {
  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen().catch(function(e) { console.warn(e); });
  } else {
    document.exitFullscreen();
  }
}
document.addEventListener('fullscreenchange', function() {
  var btn = document.getElementById('fs-btn');
  if (!btn) return;
  if (document.fullscreenElement) {
    sessionStorage.setItem('auction_fullscreen', '1');
    btn.title = 'Exit Fullscreen';
  } else {
    sessionStorage.removeItem('auction_fullscreen');
    btn.title = 'Enter Fullscreen';
  }
});
if (sessionStorage.getItem('auction_fullscreen') === '1') {
  document.documentElement.requestFullscreen().catch(function(e) { console.warn(e); });
}
